1	/// fs.rs — Read-only filesystem tools (Tier 0, Phase 1 / M1.2).
2	///
3	/// Implements `fs.read`, `fs.list`, `fs.stat` with TWO layers of defense:
4	///
5	/// 1. Pure `validate()` rejects obvious abuse (NUL bytes, percent-encoding,
6	///    backslashes) and enforces that the path is absolute and falls under a
7	///    whitelist root. Cross-platform, no IO, easy to fuzz.
8	/// 2. `openat2()` with `RESOLVE_BENEATH | RESOLVE_NO_SYMLINKS` atomically
9	///    opens within the whitelisted root. The kernel rejects any resolution
10	///    that traverses a symlink or escapes the root via `..`, so we are TOCTOU-
11	///    safe (the check and the open are one syscall).
12	///
13	/// Whitelist roots:
14	///   $HOME           — user's home directory (read access)
15	///   /proc, /sys     — kernel-exposed read-only data
16	///   /tmp            — temp scratch
17	///   /var/log        — system logs (read-only here)
18	///   /etc            — system config (read-only here)
19	///
20	/// Phase 1 reads are UTF-8 only with a 10 MB ceiling. Binary reads land in
21	/// Phase 5 alongside the base64 encoding layer. Writes (`fs.write` /
22	/// `fs.delete`) land in M1.5 with the COW gate (INV-6).
23	///
24	/// macOS dev fallback: `openat2` is Linux-only, so on macOS we fall back to
25	/// `std::fs::canonicalize` + prefix check. That fallback is for the dev loop
26	/// only — production runs on Linux with the openat2 path active.
27	use anyhow::{anyhow, bail, Result};
28	use serde_json::{json, Value};
29	use std::path::{Path, PathBuf};
30	use std::sync::OnceLock;
31	
32	const STATIC_ROOTS: &[&str] = &["/proc", "/sys", "/tmp", "/var/log", "/etc"];
33	const MAX_READ_BYTES: u64 = 10 * 1024 * 1024;
34	const MAX_WRITE_BYTES: u64 = 10 * 1024 * 1024;
35	const MAX_PATH_LEN: usize = 4096; // matches Linux PATH_MAX
36	const DEFAULT_FILE_MODE: u32 = 0o644;
37	
38	/// Subdirs under $HOME considered too sensitive to write directly even though
39	/// they are technically under $HOME. Writes here ALWAYS go through the COW
40	/// gate (INV-6). Match is by leading path component after $HOME.
41	const SENSITIVE_HOME_SUBDIRS: &[&str] = &[
42	    ".ssh", ".aws", ".gnupg", ".gpg", ".kube", ".docker", ".config/secrets",
43	];
44	
45	// ── Pure path validation ──────────────────────────────────────────────────────
46	
47	/// Result of validating a user-supplied path.
48	/// `root` is the matched whitelist root (absolute); `rel` is the path under
49	/// the root (relative, never starting with `/`). `rel` is `"."` when the user
50	/// passed the root itself (e.g. `/etc`).
51	#[derive(Debug, Clone, PartialEq, Eq)]
52	pub(crate) struct ValidatedPath {
53	    pub root: PathBuf,
54	    pub rel: String,
55	}
56	
57	fn home() -> &'static PathBuf {
58	    static HOME: OnceLock<PathBuf> = OnceLock::new();
59	    HOME.get_or_init(|| {
60	        PathBuf::from(std::env::var("HOME").unwrap_or_else(|_| "/".into()))
61	    })
62	}
63	
64	fn default_roots() -> Vec<PathBuf> {
65	    let mut v: Vec<PathBuf> = STATIC_ROOTS.iter().map(PathBuf::from).collect();
66	    v.push(home().clone());
67	    v
68	}
69	
70	/// Validate a user-supplied path against the default whitelist.
71	pub(crate) fn validate(user_path: &str) -> Result<ValidatedPath> {
72	    validate_against(user_path, &default_roots())
73	}
74	
75	/// Test-friendly variant: validate against an arbitrary root list.
76	fn validate_against(user_path: &str, roots: &[PathBuf]) -> Result<ValidatedPath> {
77	    if user_path.is_empty() {
78	        bail!("path is empty");
79	    }
80	    if user_path.len() > MAX_PATH_LEN {
81	        bail!("path exceeds PATH_MAX ({} bytes)", MAX_PATH_LEN);
82	    }
83	    if user_path.contains('\0') {
84	        bail!("path contains NUL byte");
85	    }
86	    if user_path.contains('%') {
87	        bail!("percent-encoded characters not allowed");
88	    }
89	    if user_path.contains('\\') {
90	        bail!("backslash characters not allowed");
91	    }
92	
93	    let p = Path::new(user_path);
94	    if !p.is_absolute() {
95	        bail!("path must be absolute (starts with /)");
96	    }
97	
98	    // Pick the longest matching whitelist root so e.g. /var/log wins over /
99	    // (if / were ever whitelisted) for paths like /var/log/syslog.
100	    let mut best: Option<&PathBuf> = None;
101	    for root in roots {
102	        if p.starts_with(root) {
103	            match best {
104	                None => best = Some(root),
105	                Some(b) if root.as_os_str().len() > b.as_os_str().len() => best = Some(root),
106	                _ => {}
107	            }
108	        }
109	    }
110	    let root = best.ok_or_else(|| {
111	        anyhow!("'{}' is not under any whitelisted root", user_path)
112	    })?;
113	
114	    let rel = p.strip_prefix(root)
115	        .map_err(|_| anyhow!("internal: strip_prefix failed"))?;
116	    let rel_str = if rel.as_os_str().is_empty() {
117	        ".".to_string()
118	    } else {
119	        rel.to_string_lossy().into_owned()
120	    };
121	
122	    Ok(ValidatedPath { root: root.clone(), rel: rel_str })
123	}
124	
125	// ── Tool functions ────────────────────────────────────────────────────────────
126	
127	pub async fn read(path: &str) -> Result<Value> {
128	    let v = validate(path)?;
129	    let mut file = safe_open_readonly(&v.root, &v.rel)?;
130	    let metadata = file.metadata()?;
131	    if metadata.is_dir() {
132	        bail!("path is a directory; use fs.list instead");
133	    }
134	    if metadata.len() > MAX_READ_BYTES {
135	        bail!("file too large ({} bytes > {} max)", metadata.len(), MAX_READ_BYTES);
136	    }
137	    use std::io::Read;
138	    let mut content = String::new();
139	    file.read_to_string(&mut content)
140	        .map_err(|e| anyhow!("not valid UTF-8 (binary reads land in Phase 5): {}", e))?;
141	    Ok(json!({
142	        "path": path,
143	        "size_bytes": metadata.len(),
144	        "content": content,
145	    }))
146	}
147	
148	pub async fn list(path: &str) -> Result<Value> {
149	    let v = validate(path)?;
150	    // openat2 with O_DIRECTORY confirms no symlink escape; we then enumerate
151	    // via std::fs::read_dir on the resolved full path. The TOCTOU window is
152	    // tiny and Landlock (M1.3) closes it at the kernel level.
153	    let _dir_fd = safe_open_directory(&v.root, &v.rel)?;
154	
155	    let full = if v.rel == "." { v.root.clone() } else { v.root.join(&v.rel) };
156	    let mut entries = Vec::new();
157	    for entry in std::fs::read_dir(&full)? {
158	        let entry = entry?;
159	        let name = entry.file_name().to_string_lossy().into_owned();
160	        let metadata = entry.metadata().ok();
161	        entries.push(json!({
162	            "name": name,
163	            "is_dir": metadata.as_ref().map(|m| m.is_dir()).unwrap_or(false),
164	            "is_symlink": entry.file_type().ok().map(|t| t.is_symlink()).unwrap_or(false),
165	            "size_bytes": metadata.as_ref().map(|m| m.len()).unwrap_or(0),
166	        }));
167	    }
168	    entries.sort_by(|a, b| a["name"].as_str().cmp(&b["name"].as_str()));
169	
170	    Ok(json!({
171	        "path": path,
172	        "count": entries.len(),
173	        "entries": entries,
174	    }))
175	}
