177	/// fs.write — Tier 1 inside safe $HOME, Tier 3 (COW gate) everywhere else.
178	/// INV-6: writes outside $HOME never execute synchronously in Phase 1.
179	pub async fn write(path: &str, content: &str, mode: Option<u32>) -> Result<Value> {
180	    let v = validate(path)?;
181	    if content.len() as u64 > MAX_WRITE_BYTES {
182	        bail!("content too large ({} bytes > {} max)", content.len(), MAX_WRITE_BYTES);
183	    }
184	
185	    if !is_tier_1_safe(&v) {
186	        return Ok(cow_gate_response("fs.write", path, content.len() as u64));
187	    }
188	
189	    let mode = mode.unwrap_or(DEFAULT_FILE_MODE);
190	    safe_write(&v.root, &v.rel, content, mode)?;
191	    Ok(json!({
192	        "status": "ok",
193	        "path": path,
194	        "bytes_written": content.len(),
195	        "mode": format!("{:o}", mode),
196	    }))
197	}
198	
199	/// fs.delete — ALWAYS Tier 3 per the catalogue. Never executes synchronously
200	/// in Phase 1; the response is always a COW gate ticket.
201	pub async fn delete(path: &str) -> Result<Value> {
202	    let v = validate(path)?;
203	    // Capture metadata so the preview is useful even before Phase 3 commits.
204	    let preview_size = safe_open_readonly(&v.root, &v.rel)
205	        .ok()
206	        .and_then(|f| f.metadata().ok())
207	        .map(|m| m.len())
208	        .unwrap_or(0);
209	    Ok(cow_gate_response_with_size("fs.delete", path, preview_size, 0))
210	}
211	
212	/// `Tier 1` predicate: under $HOME and NOT in a sensitive subdir.
213	fn is_tier_1_safe(v: &ValidatedPath) -> bool {
214	    if v.root != *home() {
215	        return false;
216	    }
217	    // v.rel is relative to $HOME. Reject if it starts with any sensitive subdir.
218	    let rel = v.rel.as_str();
219	    for sub in SENSITIVE_HOME_SUBDIRS {
220	        if rel == *sub || rel.starts_with(&format!("{}/", sub)) {
221	            return false;
222	        }
223	    }
224	    true
225	}
226	
227	/// Build a Tier 3 COW gate response (INV-6). Phase 3 will accept this
228	/// `intent_id` and run the actual COW commit pipeline.
229	fn cow_gate_response(operation: &str, path: &str, proposed_size: u64) -> Value {
230	    cow_gate_response_with_size(operation, path, 0, proposed_size)
231	}
232	
233	fn cow_gate_response_with_size(
234	    operation: &str,
235	    path: &str,
236	    current_size: u64,
237	    proposed_size: u64,
238	) -> Value {
239	    json!({
240	        "status": "requires_cow_approval",
241	        "intent_id": uuid::Uuid::new_v4().to_string(),
242	        "preview": {
243	            "operation": operation,
244	            "path": path,
245	            "current_size_bytes": current_size,
246	            "proposed_size_bytes": proposed_size,
247	        },
248	    })
249	}
250	
251	pub async fn stat(path: &str) -> Result<Value> {
252	    let v = validate(path)?;
253	    let file = safe_open_readonly(&v.root, &v.rel)?;
254	    let metadata = file.metadata()?;
255	    #[cfg(unix)]
256	    use std::os::unix::fs::MetadataExt;
257	
258	    #[cfg(unix)]
259	    let extra = json!({
260	        "mode": format!("{:o}", metadata.mode() & 0o7777),
261	        "uid":  metadata.uid(),
262	        "gid":  metadata.gid(),
263	        "mtime": metadata.mtime(),
264	    });
265	    #[cfg(not(unix))]
266	    let extra = json!({});
267	
268	    Ok(json!({
269	        "path": path,
270	        "size_bytes": metadata.len(),
271	        "is_dir":     metadata.is_dir(),
272	        "is_file":    metadata.is_file(),
273	        "is_symlink": metadata.file_type().is_symlink(),
274	        "extra": extra,
275	    }))
276	}
