278	// ── openat2 — direct libc syscall, since nix 0.28 doesn't expose it ─────────
279	
280	#[cfg(target_os = "linux")]
281	mod openat2 {
282	    use anyhow::{anyhow, Result};
283	    use std::ffi::CString;
284	    use std::io;
285	    use std::os::fd::RawFd;
286	
287	    // From include/uapi/linux/openat2.h.
288	    #[repr(C)]
289	    pub(super) struct OpenHow {
290	        pub flags: u64,
291	        pub mode: u64,
292	        pub resolve: u64,
293	    }
294	
295	    // Flag values from include/uapi/asm-generic/fcntl.h
296	    const O_RDONLY:    u64 = 0;
297	    const O_WRONLY:    u64 = 1;
298	    const O_CREAT:     u64 = 0o100;
299	    const O_TRUNC:     u64 = 0o1000;
300	    const O_DIRECTORY: u64 = 0o200_000;
301	    const O_CLOEXEC:   u64 = 0o2_000_000;
302	
303	    // Resolve flags from include/uapi/linux/openat2.h
304	    const RESOLVE_NO_SYMLINKS: u64 = 0x04;
305	    const RESOLVE_BENEATH:     u64 = 0x08;
306	
307	    const RESOLVE_STRICT: u64 = RESOLVE_BENEATH | RESOLVE_NO_SYMLINKS;
308	
309	    impl OpenHow {
310	        pub fn read_only() -> Self {
311	            OpenHow {
312	                flags: O_RDONLY | O_CLOEXEC,
313	                mode: 0,
314	                resolve: RESOLVE_STRICT,
315	            }
316	        }
317	        pub fn read_only_directory() -> Self {
318	            OpenHow {
319	                flags: O_RDONLY | O_DIRECTORY | O_CLOEXEC,
320	                mode: 0,
321	                resolve: RESOLVE_STRICT,
322	            }
323	        }
324	        pub fn write_create_trunc(mode: u32) -> Self {
325	            OpenHow {
326	                flags: O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC,
327	                mode: mode as u64,
328	                resolve: RESOLVE_STRICT,
329	            }
330	        }
331	    }
332	
333	    pub(super) fn call(dirfd: RawFd, path: &str, how: &OpenHow) -> Result<RawFd> {
334	        let c_path = CString::new(path)
335	            .map_err(|e| anyhow!("path contained NUL: {}", e))?;
336	        let ret = unsafe {
337	            libc::syscall(
338	                libc::SYS_openat2,
339	                dirfd,
340	                c_path.as_ptr(),
341	                how as *const OpenHow,
342	                std::mem::size_of::<OpenHow>(),
343	            )
344	        };
345	        if ret < 0 {
346	            return Err(anyhow!("openat2: {}", io::Error::last_os_error()));
347	        }
348	        Ok(ret as RawFd)
349	    }
350	}
351	
352	// ── safe_open: openat2 on Linux, canonicalize-check on macOS ─────────────────
353	
354	#[cfg(target_os = "linux")]
355	fn safe_open_readonly(root: &Path, rel: &str) -> Result<std::fs::File> {
356	    use std::os::fd::{AsRawFd, FromRawFd};
357	    let dir = std::fs::File::open(root)
358	        .map_err(|e| anyhow!("cannot open whitelist root '{}': {}", root.display(), e))?;
359	    let how = openat2::OpenHow::read_only();
360	    let fd = openat2::call(dir.as_raw_fd(), rel, &how)
361	        .map_err(|e| anyhow!("openat2 refused '{}': {}", rel, e))?;
362	    Ok(unsafe { std::fs::File::from_raw_fd(fd) })
363	}
364	
365	#[cfg(not(target_os = "linux"))]
366	fn safe_open_readonly(root: &Path, rel: &str) -> Result<std::fs::File> {
367	    let full = if rel == "." { root.to_path_buf() } else { root.join(rel) };
368	    let canonical = std::fs::canonicalize(&full)
369	        .map_err(|e| anyhow!("canonicalize failed: {}", e))?;
370	    let root_canon = std::fs::canonicalize(root)
371	        .map_err(|e| anyhow!("canonicalize root failed: {}", e))?;
372	    if !canonical.starts_with(&root_canon) {
373	        bail!("path escapes root after canonicalization (symlink?): {:?}", canonical);
374	    }
375	    std::fs::File::open(&canonical).map_err(|e| anyhow!("open failed: {}", e))
376	}
377	
378	#[cfg(target_os = "linux")]
379	fn safe_write(root: &Path, rel: &str, content: &str, mode: u32) -> Result<()> {
380	    use std::io::Write;
381	    use std::os::fd::{AsRawFd, FromRawFd};
382	    let dir = std::fs::File::open(root)
383	        .map_err(|e| anyhow!("cannot open whitelist root '{}': {}", root.display(), e))?;
384	    let how = openat2::OpenHow::write_create_trunc(mode);
385	    let fd = openat2::call(dir.as_raw_fd(), rel, &how)
386	        .map_err(|e| anyhow!("openat2(write) refused '{}': {}", rel, e))?;
387	    let mut file = unsafe { std::fs::File::from_raw_fd(fd) };
388	    file.write_all(content.as_bytes())
389	        .map_err(|e| anyhow!("write failed: {}", e))?;
390	    file.sync_all().ok();
391	    Ok(())
392	}
393	
394	#[cfg(not(target_os = "linux"))]
395	fn safe_write(root: &Path, rel: &str, content: &str, mode: u32) -> Result<()> {
396	    use std::io::Write;
397	    use std::os::unix::fs::OpenOptionsExt;
398	    let full = root.join(rel);
399	    // canonicalize the parent so we catch symlink-escape attempts; the file
400	    // itself may not exist yet.
401	    if let Some(parent) = full.parent() {
402	        let root_canon = std::fs::canonicalize(root)
403	            .map_err(|e| anyhow!("canonicalize root failed: {}", e))?;
404	        let parent_canon = std::fs::canonicalize(parent)
405	            .map_err(|e| anyhow!("canonicalize parent failed: {}", e))?;
406	        if !parent_canon.starts_with(&root_canon) {
407	            bail!("write target escapes root after canonicalization: {:?}", parent_canon);
408	        }
409	    }
410	    let mut file = std::fs::OpenOptions::new()
411	        .write(true)
412	        .create(true)
413	        .truncate(true)
414	        .mode(mode)
415	        .open(&full)
416	        .map_err(|e| anyhow!("open(write) failed: {}", e))?;
417	    file.write_all(content.as_bytes())
418	        .map_err(|e| anyhow!("write failed: {}", e))?;
419	    Ok(())
420	}
421	
422	#[cfg(target_os = "linux")]
423	fn safe_open_directory(root: &Path, rel: &str) -> Result<std::fs::File> {
424	    use std::os::fd::{AsRawFd, FromRawFd};
425	    let dir = std::fs::File::open(root)?;
426	    let how = openat2::OpenHow::read_only_directory();
427	    let fd = openat2::call(dir.as_raw_fd(), rel, &how)
428	        .map_err(|e| anyhow!("openat2(dir) refused '{}': {}", rel, e))?;
429	    Ok(unsafe { std::fs::File::from_raw_fd(fd) })
430	}
431	
432	#[cfg(not(target_os = "linux"))]
433	fn safe_open_directory(root: &Path, rel: &str) -> Result<std::fs::File> {
434	    safe_open_readonly(root, rel)
435	}
