437	// ── Unit tests for validate() — adversarial path corpus ──────────────────────
438	
439	#[cfg(test)]
440	mod tests {
441	    use super::*;
442	
443	    fn roots() -> Vec<PathBuf> {
444	        vec![
445	            PathBuf::from("/proc"),
446	            PathBuf::from("/sys"),
447	            PathBuf::from("/tmp"),
448	            PathBuf::from("/var/log"),
449	            PathBuf::from("/etc"),
450	            PathBuf::from("/home/aditya"),
451	        ]
452	    }
