454	    // ── Happy paths ───────────────────────────────────────────────────────────
455	
456	    #[test]
457	    fn validate_etc_hosts() {
458	        let v = validate_against("/etc/hosts", &roots()).unwrap();
459	        assert_eq!(v.root, PathBuf::from("/etc"));
460	        assert_eq!(v.rel, "hosts");
461	    }
462	
463	    #[test]
464	    fn validate_proc_pid_status() {
465	        let v = validate_against("/proc/1/status", &roots()).unwrap();
466	        assert_eq!(v.root, PathBuf::from("/proc"));
467	        assert_eq!(v.rel, "1/status");
468	    }
