470	    #[test]
471	    fn validate_home_file() {
472	        let v = validate_against("/home/aditya/.bashrc", &roots()).unwrap();
473	        assert_eq!(v.root, PathBuf::from("/home/aditya"));
474	        assert_eq!(v.rel, ".bashrc");
