477	    #[test]
478	    fn validate_root_itself_yields_dot() {
479	        let v = validate_against("/etc", &roots()).unwrap();
480	        assert_eq!(v.root, PathBuf::from("/etc"));
481	        assert_eq!(v.rel, ".");
