489	
490	    #[test]
491	    fn validate_longest_root_wins() {
492	        // /var/log should win over an imagined / root for this path.
493	        let v = validate_against("/var/log/syslog", &roots()).unwrap();
494	        assert_eq!(v.root, PathBuf::from("/var/log"));
495	        assert_eq!(v.rel, "syslog");
