498	    #[test]
499	    fn validate_deep_nested_path() {
500	        let v = validate_against("/proc/1/fd/0", &roots()).unwrap();
501	        assert_eq!(v.rel, "1/fd/0");
502	    }
503	
504	    // ── Whitelist enforcement ─────────────────────────────────────────────────
505	
506	    #[test]
507	    fn rejects_path_outside_whitelist() {
508	        assert!(validate_against("/root/.ssh/id_rsa", &roots()).is_err());
509	        assert!(validate_against("/boot/grub/grub.cfg", &roots()).is_err());
510	        assert!(validate_against("/var/lib/mysql/data", &roots()).is_err());
511	        assert!(validate_against("/opt/secret", &roots()).is_err());
512	        assert!(validate_against("/usr/bin/sudo", &roots()).is_err());
513	    }
