515	    #[test]
516	    fn rejects_other_user_home() {
517	        assert!(validate_against("/home/otheruser/.ssh/id_rsa", &roots()).is_err());
518	    }
519	
520	    #[test]
521	    fn rejects_path_that_only_partially_matches_root() {
522	        // /etcpasswd is NOT under /etc, even though string-prefix matches.
523	        assert!(validate_against("/etcpasswd", &roots()).is_err());
524	        assert!(validate_against("/etc-public/foo", &roots()).is_err());
525	        assert!(validate_against("/procbar/x", &roots()).is_err());
