528	    // ── Format rejection ──────────────────────────────────────────────────────
529	
530	    #[test]
531	    fn rejects_empty_path() {
532	        assert!(validate_against("", &roots()).is_err());
533	    }
534	
535	    #[test]
536	    fn rejects_relative_path() {
537	        assert!(validate_against("etc/hosts", &roots()).is_err());
538	        assert!(validate_against("./etc/hosts", &roots()).is_err());
539	        assert!(validate_against("../etc/hosts", &roots()).is_err());
540	        assert!(validate_against("hosts", &roots()).is_err());
541	    }
