738	    //
739	    // We can't directly assert is_tier_1_safe() without overriding home(),
740	    // so we test the *exact rule* with a parallel helper.
741	    fn tier1_test(v: &ValidatedPath, fake_home: &Path) -> bool {
742	        if v.root != *fake_home {
743	            return false;
744	        }
745	        for sub in SENSITIVE_HOME_SUBDIRS {
746	            if v.rel == *sub || v.rel.starts_with(&format!("{}/", sub)) {
747	                return false;
748	            }
749	        }
750	        true
751	    }
