791	    // ── Property test: 10k pseudorandom paths must never escape (G4) ────────
792	    //
793	    // The hand-curated corpus above proves we reject the *known* attacks.
794	    // This generative test guards against the unknown-unknowns: we synthesize
795	    // 10,000 random byte sequences (biased toward known-bad chars) and assert:
796	    //   (a) validate() never panics
797	    //   (b) any path it accepts strips down to a root from our whitelist
798	    //   (c) the relative portion never contains literal NUL/%/\
799	    // openat2(RESOLVE_BENEATH) is the kernel-side layer that catches ".."
800	    // escapes at actual open; we don't simulate that here.
801	    //
802	    // Uses a simple LCG so the test is deterministic and dependency-free.
803	
804	    fn lcg_next(state: &mut u64) -> u64 {
805	        // Numerical Recipes constants.
806	        *state = state.wrapping_mul(1664525).wrapping_add(1013904223);
807	        *state
808	    }
809	
810	    fn synth_path(rng: &mut u64) -> String {
811	        // 5% NUL, 8% %, 8% \\, 12% '..', 12% '/', remainder lower-ascii.
812	        let len = (lcg_next(rng) % 96 + 2) as usize;
813	        let mut s = String::with_capacity(len);
814	        for _ in 0..len {
815	            let r = (lcg_next(rng) % 100) as u8;
816	            let ch = match r {
817	                0..=4   => '\0',
818	                5..=12  => '%',
819	                13..=20 => '\\',
820	                21..=32 => '.',
821	                33..=44 => '/',
822	                45..=49 => '~',
823	                50..=59 => 'a',
824	                60..=69 => 'b',
825	                70..=79 => '1',
826	                80..=89 => '-',
827	                _       => '_',
828	            };
829	            s.push(ch);
830	        }
831	        s
832	    }
833	
834	    #[test]
835	    fn fuzz_validate_never_panics_or_escapes() {
836	        let mut rng: u64 = 0xCAFE_F00D_DEAD_BEEF; // fixed seed
837	        let mut accepted = 0;
838	        let mut rejected = 0;
839	        let roots = roots();
840	        for _ in 0..10_000 {
841	            let p = synth_path(&mut rng);
842	            // No prefix to bias toward whitelist; let validate find a match
843	            // if any (most won't).
844	            match validate_against(&p, &roots) {
845	                Ok(v) => {
846	                    accepted += 1;
847	                    // Must match a whitelist root exactly.
848	                    assert!(
849	                        roots.contains(&v.root),
850	                        "accepted root '{}' not in whitelist: input={:?}",
851	                        v.root.display(), p
852	                    );
853	                    // Rel must not contain disallowed bytes (validate strips
854	                    // NUL/% rejection before strip_prefix).
855	                    assert!(!v.rel.contains('\0'), "NUL leaked into rel: {:?}", v.rel);
856	                    assert!(!v.rel.contains('%'), "% leaked into rel: {:?}", v.rel);
857	                    assert!(!v.rel.contains('\\'), "\\ leaked into rel: {:?}", v.rel);
858	                }
859	                Err(_) => {
860	                    rejected += 1;
861	                }
862	            }
863	        }
864	        // Sanity: the corpus must produce both shapes.
865	        assert!(accepted + rejected == 10_000);
866	        // Anything else would indicate a regression in our character bias
867	        // (we want a non-trivial mix).
868	        assert!(rejected > 1000, "expected substantial rejection rate, got {}", rejected);
869	    }
870	}
