1	//! Integration tests for mcpd.
2	//!
3	//! Spawns the mcpd binary, pipes JSON-RPC requests to its stdin, and reads
4	//! responses from its stdout. The stdio protocol is what the Controller will
5	//! use, so these tests exercise the real wire format.
6	//!
7	//! Tests that don't touch /proc run on any OS (macOS dev loop). Tests that
8	//! depend on /proc are gated with #[cfg(target_os = "linux")].
9	
10	use serde_json::{json, Value};
11	use std::io::{BufRead, BufReader, Write};
12	use std::process::{Child, ChildStdin, ChildStdout, Command, Stdio};
13	
14	fn unique_audit_path() -> std::path::PathBuf {
15	    use std::time::{SystemTime, UNIX_EPOCH};
16	    let stamp = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
17	    std::env::temp_dir().join(format!("mcpd-audit-test-{}-{}.log", std::process::id(), stamp))
18	}
19	
20	/// A handle to a running mcpd subprocess plus line-buffered stdio.
21	struct Mcpd {
22	    child: Child,
23	    stdin: ChildStdin,
24	    stdout: BufReader<ChildStdout>,
25	}
26	
27	impl Mcpd {
28	    fn spawn() -> Self {
29	        Self::spawn_with_audit(None)
30	    }
31	
32	    fn spawn_with_audit(audit_path: Option<&std::path::Path>) -> Self {
33	        let bin = env!("CARGO_BIN_EXE_mcpd");
34	        let mut cmd = Command::new(bin);
35	        cmd.stdin(Stdio::piped())
36	            .stdout(Stdio::piped())
37	            .stderr(Stdio::null());
38	        if let Some(p) = audit_path {
39	            cmd.env("MCPD_AUDIT_LOG", p);
40	        }
41	        let mut child = cmd.spawn().expect("spawn mcpd");
42	        let stdin = child.stdin.take().expect("stdin");
43	        let stdout = BufReader::new(child.stdout.take().expect("stdout"));
44	        Self { child, stdin, stdout }
45	    }
46	
47	    /// Send a JSON-RPC request and parse one response line.
48	    fn call(&mut self, req: &Value) -> Value {
49	        let line = req.to_string() + "\n";
50	        self.stdin.write_all(line.as_bytes()).expect("write");
51	        self.stdin.flush().expect("flush");
52	        let mut resp_line = String::new();
53	        self.stdout.read_line(&mut resp_line).expect("read");
54	        serde_json::from_str(&resp_line).expect("parse response")
55	    }
56	
57	    /// Send a raw line (may be malformed JSON).
58	    fn call_raw(&mut self, raw: &str) -> Value {
59	        self.stdin.write_all(raw.as_bytes()).expect("write");
60	        self.stdin.write_all(b"\n").expect("write");
61	        self.stdin.flush().expect("flush");
62	        let mut resp_line = String::new();
63	        self.stdout.read_line(&mut resp_line).expect("read");
64	        serde_json::from_str(&resp_line).expect("parse response")
65	    }
66	}
67	
68	impl Drop for Mcpd {
69	    fn drop(&mut self) {
70	        // EOF triggers graceful shutdown; if that doesn't work, kill it.
71	        let _ = self.child.kill();
72	        let _ = self.child.wait();
73	    }
74	}
