289	fn fs_read_round_trip_with_tempfile() {
290	    use std::io::Write;
291	    let dir = std::env::temp_dir();
292	    let unique = format!("mcpd_test_{}.txt", std::process::id());
293	    let path = dir.join(&unique);
294	    {
295	        let mut f = std::fs::File::create(&path).unwrap();
296	        f.write_all(b"hello mcpd\n").unwrap();
297	    }
298	    let abs = path.to_str().unwrap().to_string();
299	
300	    // Skip if the temp dir isn't under our whitelist (e.g. macOS uses /var/folders/...
301	    // which is symlinked to /private/var/folders/... — neither is in the v1 whitelist).
302	    let whitelisted = abs.starts_with("/tmp/") || abs.starts_with("/var/log/");
303	    if !whitelisted {
304	        let _ = std::fs::remove_file(&path);
305	        eprintln!("skipping: temp dir {} is not under whitelist root", abs);
306	        return;
307	    }
308	
309	    let mut mcpd = Mcpd::spawn();
310	    let resp = mcpd.call(&json!({
311	        "jsonrpc": "2.0",
312	        "method": "fs.read",
313	        "params": {"path": abs},
314	        "id": 1,
315	    }));
316	
317	    let _ = std::fs::remove_file(&path);
318	
319	    assert!(resp["error"].is_null(), "expected ok response, got error: {:?}", resp["error"]);
320	    assert_eq!(resp["result"]["content"], "hello mcpd\n");
321	    assert_eq!(resp["result"]["size_bytes"], 11);
322	}
