639	#[test]
640	fn audit_writes_one_line_per_request() {
641	    let path = unique_audit_path();
642	    let mut mcpd = Mcpd::spawn_with_audit(Some(&path));
643	
644	    let _ = mcpd.call(&json!({"jsonrpc": "2.0", "method": "tools/list", "id": 1}));
645	    let _ = mcpd.call(&json!({"jsonrpc": "2.0", "method": "nope.method", "id": 2}));
646	    let _ = mcpd.call(&json!({
647	        "jsonrpc": "2.0",
648	        "method": "fs.read",
649	        "params": {"path": "/etc/hosts"},
650	        "id": 3,
651	    }));
652	
653	    // Force the child to exit so its file handle flushes.
654	    drop(mcpd);
655	    std::thread::sleep(std::time::Duration::from_millis(100));
656	
657	    let content = std::fs::read_to_string(&path)
658	        .expect("audit file should exist after the 3 calls");
659	    let lines: Vec<&str> = content.lines().filter(|l| !l.is_empty()).collect();
660	    let _ = std::fs::remove_file(&path);
661	
662	    assert_eq!(lines.len(), 3, "expected 3 lines, got {}: {:?}", lines.len(), lines);
663	    for line in &lines {
664	        let v: Value = serde_json::from_str(line).expect("each line is JSON");
665	        assert!(v["timestamp"].is_string());
666	        assert!(v["method"].is_string());
667	        assert!(v["result_class"].is_string());
668	        assert!(v["latency_us"].is_number());
669	    }
670	    // Spot-check result_class mapping.
671	    let classes: Vec<&str> = lines.iter()
672	        .map(|l| serde_json::from_str::<Value>(l).unwrap()["result_class"].as_str().unwrap().to_string())
673	        .map(|s| Box::leak(s.into_boxed_str()) as &str)
674	        .collect();
675	    assert!(classes.contains(&"ok"));
676	    assert!(classes.contains(&"method_not_found"));
677	}
